.Attachment{} if len(request.Memo.Attachments) > 0 { if err := s.setMemoAttachmentsInternal(ctx, user, memo, request.Memo.Attachments); err != nil { return nil, errors.Wrap(err, \"failed to set memo attachments\") } a, err := s.Store.ListAttachments(ctx, &store.FindAttachment{ MemoID: &memo.ID, }) if err != nil { return nil, errors.Wrap(err, \"failed to get memo attachments\") } attachments = a } if len(request.Memo.Relations) > 0 { if err := s.setMemoRelationsInternal(ctx, memo, request.Memo.Relations); err != nil { return nil, errors.Wrap(err, \"failed to set memo relations\") } } relations, err := s.loadMemoRelations(ctx, memo) if err != nil { return nil, errors.Wrap(err, \"failed to load memo relations\") } memoMessage, err := s.convertMemoFromStore(ctx, memo, nil, attachments, relations) if err != nil { return nil, errors.Wrap(err, \"failed to convert memo\") } // Try to dispatch webhook when memo is created. if err := s.DispatchMemoCreatedWebhook(ctx, memoMessage); err != nil { slog.Warn(\"Failed to dispatch memo created webhook\", slog.Any(\"err\", err)) } // Broadcast live refresh event (skipped when called from CreateMemoComment). if !isSSESuppressed(ctx) { s.SSEHub.Broadcast(&SSEEvent{ Type:       SSEEventMemoCreated, Name:       memoMessage.Name, Visibility: memo.Visibility, CreatorID:  resolveSSECreatorID(memo, nil), }) } if !isMentionNotificationSuppressed(ctx) { s.dispatchMemoMentionNotificationsBestEffort(ctx, memo, nil, \"\") } return memoMessage, nil } func (s *APIV1Service) ListMemos(ctx context.Context, request *v1pb.ListMemosRequest) (*v1pb.ListMemosResponse, error) {"
